arguments.old_str:
using System.Collections.Generic;
using Xunit;

namespace MyApp.Tests;

public class DiscountTests
{
    public static IEnumerable<object[]> Cases =>
        new[]
        {
            new object[] { 100m, 10, 90m },
            new object[] { 200m, 25, 150m },
        };

    [Theory]
    [MemberData(nameof(Cases))]
    public void Apply_ReturnsExpected(decimal price, int percent, decimal expected)
    {
        var actual = price - (price * percent / 100m);
        Assert.Equal(expected, actual);
    }
}

arguments.new_str:
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Tests;

[TestClass]
public class DiscountTests
{
    [TestMethod]
    [DataRow(100, 10, 90)]
    [DataRow(200, 25, 150)]
    public void Apply_ReturnsExpected(int price, int percent, int expected)
    {
        var actual = (decimal)price - ((decimal)price * percent / 100m);
        Assert.AreEqual((decimal)expected, actual);
    }
}

